def run(api):
    state = api.inspect('state')
    if state.get('healthy', False):
        if not state['expanded']:
            api.apply('expand')
        if not state['capturing']:
            api.apply('capture_changes')
        if not state['copied']:
            api.apply('backfill')
        if not state['audited']:
            api.apply('audit_backfill')
        if not state['compatibility']:
            api.apply('install_compatibility')
        if not state['new_traffic']:
            api.apply('cutover')
        if state['legacy_readers']:
            api.apply('drain_legacy_readers')
        if state['old_schema']:
            api.apply('drop_old_schema')
        if state['capturing']:
            api.apply('remove_capture')
        if state['compatibility']:
            api.apply('remove_compatibility')
    else:
        if not state['expanded']:
            api.apply('expand')
        if not state['capturing']:
            api.apply('capture_changes')
        if not state['copied']:
            api.apply('backfill')
        if not state['audited']:
            api.apply('audit_backfill')
        if state['expanded']:
            api.apply('rollback_expansion')

